function paper() {
  if (d().ext === "EPUB")
    return `<article class="paper book"><div class="chapter">CHAPTER THREE</div><h1>The small things<br>are the big things.</h1><div class="dek">An invitation to look again.</div><p class="drop">There is a certain kind of attention that asks nothing of the world. It simply makes room for what is already there.</p><p>The changing light on a kitchen wall. A handwritten sign in a shop window. The first soft green of a tree you pass each morning.</p><p>We often imagine that noticing requires a new place. More often, it requires a little time in a familiar one.</p><h2>Begin where you are</h2><p>Take the longer way home. Leave a little space around your plans. Notice what happens when you stop looking for something in particular.</p><div class="page-bottom"><span>The art of noticing</span><span>Sample passage</span></div></article>`;
  if (d().ext === "MD")
    return `<article class="paper markdown"><div class="eyebrow">STUDIO / WORKING NOTES</div><h1>Field notes<br>on a quieter space.</h1><p>Observations from a week of looking at the places where we work.</p><div class="note">A room is useful when it makes the next small action feel easy.</div><h2>01 / Materials</h2><p>Keep the palette simple. Natural light, warm paper, unfinished wood. Let one material carry the room.</p><ul><li>Matte surfaces near the window</li><li>One clear place to begin</li><li>Objects with a reason to be here</li></ul><h2>02 / A small experiment</h2><div class="code"><code>space:\n  light: natural\n  objects: fewer\n  attention: undivided</code></div><h2>03 / Next visit</h2><p>Return in the late afternoon. The light will have changed; perhaps the room will feel different, too.</p><div class="page-bottom"><span>STUDIO FIELD NOTES.MD</span><span>Sample Markdown</span></div></article>`;
  return `<article class="paper"><div class="paper-kicker"><span>SPACES FOR LIVING</span><span>04 / ESSAYS</span></div><h1>${state.doc === 0 ? "A room<br>for thought." : d().title + "."}</h1><div class="dek">On light, stillness, and the things<br>we choose to leave room for.</div><div class="byline">Words by the studio · Autumn 2026</div><div class="diagram" aria-label="Architectural line illustration of a quiet room"><svg viewBox="0 0 280 113"><path d="M18 83h239 M55 78V19h87v59 M63 72V27h71v45 M98 27v45 M63 49h71 M148 78V44h86v34 M156 78V52h70v26 M160 52l18-17h42v17 M34 82V67h25v15 M30 67h33 M236 82V65 M228 65h17 M235 65c-17-7-5-24 1-11 10-21 20 0 0 11 M26 94h213"/><path d="m55 78-11 5m98-5 15 5 M173 83l-10 10 M207 83l21 10"/></svg></div><p class="drop">A quiet room is not an empty room. It is a place where the necessary things have room to breathe, and the unnecessary things no longer ask for our attention.</p><p>Light moves across the floor. A chair waits beside the window. Between these ordinary things, a different rhythm begins to appear.</p><h2>Leave a little room.</h2><p>Perhaps the most useful thing we can add to a space is the possibility of doing less within it.</p><div class="page-bottom"><span>A room for thought</span><span>12</span></div></article>`;
}
function reader() {
  return `${header(d().title, state.older ? `${state.missing && state.preferredRecoveryDate && !state.unverified && state.revisionDate === state.preferredRecoveryDate ? "Latest verified" : "Older version"} · ${state.revisionDate || "18 Sep 2026"}` : state.missing ? "Saved copy · Original unavailable" : d().meta, "groups")}${state.older ? `<div class="notice">${icon("history")}<span>Reading a saved, read-only version</span>${revisionReturnControl()}</div>` : ""}${state.missing ? `<div class="notice">${icon("link")}<span>Your saved copy is available.</span><button data-action="missing">Find original</button></div>` : ""}<main class="scroll reader-scroll" aria-label="${d().ext} sample reading surface">${paper()}</main><div class="reading-progress"><span>${d().position}</span><span>${state.older ? `Saved ${state.revisionDate || "18 Sep 2026"}` : d().group}</span></div><nav class="nav reader-nav" aria-label="Reader tools">${["contents", "find", "switcher", "more"].map((x, i) => `<button ${x === "switcher" ? 'id="switch-control" class="switch-button"' : ""} data-action="${x}"><span class="icon-wrap">${icon(["contents", "search", "wheel", "more"][i])}</span>${["Contents", "Find", "Switch", "More"][i]}</button>`).join("")}</nav>`;
}
function groupScreen() {
  return `<div class="heading"><div class="row between"><div><div class="eyebrow">YOUR WORKING SET</div><h1>Groups</h1></div><div class="row" style="gap:0">${btn("globalsearch", "Search everything", "search")}${btn("newgroup", "Create group", "plus")}</div></div><p class="subtitle">A place for everything you’re reading.</p></div><main class="scroll"><div class="content"><div class="field">${icon("search")}<input id="group-search" aria-label="Search group names" placeholder="Find a group" value="${escapeHtml(state.query)}"></div><div class="section-title"><h2>Pick up where you left off</h2></div><button class="card continue" data-action="reader" style="width:100%;text-align:left">${thumb(d())}<div class="grow"><div class="eyebrow">${d().ext} · ${d().group}</div><h3>${d().title}</h3><small>${d().position}</small><div class="mini-progress"><i></i></div></div>${icon("arrow")}</button><div class="section-title" style="margin-top:25px"><h2>Your groups</h2><span>${groups.length} groups</span></div><div class="card" id="group-results">${groupRows()}</div><div class="group-footer"><p>Organize here. Read without clutter.</p></div><button class="secondary" data-action="open">${icon("plus")}Open a document</button></div></main>${nav("groups")}`;
}
function groupRows() {
  const arr = groups
    .map((g, i) => ({ ...g, i }))
    .filter((g) => g.name.toLowerCase().includes(state.query.toLowerCase()));
  return arr.length
    ? arr
        .map(
          (g) =>
            `<button class="group-row" data-action="group:${g.i}"><span class="group-icon ${g.color}">${icon("groups")}</span><span class="grow"><strong>${escapeHtml(g.name)}</strong><small>${g.sub}</small></span><span class="count">${g.count}</span>${icon("chevron")}</button>`,
        )
        .join("")
    : '<div class="empty">No group names match.</div>';
}
function docRows(list, collection = false) {
  return list
    .map(
      (doc) =>
        `<div class="doc-row"><button class="doc-main" data-action="${collection && state.query.trim() ? "hit" : "doc"}:${doc.id}">${thumb(doc)}<span class="grow"><strong>${doc.title}</strong><small>${doc.ext} · ${doc.position}</small>${collection ? `<p>${markedText(plainSnippet(doc), state.query)}</p>` : ""}</span></button>${btn(`docmenu:${doc.id}`, `Options for ${doc.title}`, "more")}</div>`,
    )
    .join("");
}
function documents() {
  const g = groups[state.group];
  return `${header(g.name, `${g.count} documents`, "groups", "groupmenu")}<main class="scroll"><div class="content"><div class="section-title"><h2>In this group</h2><span>Manual order</span></div>${docRows(docs.filter((doc) => doc.group === g.name)) || '<div class="empty"><p>No documents yet.</p><p>Open a sample into this group.</p></div>'}<button class="secondary" style="margin-top:22px" data-action="open">${icon("plus")}Open into this group</button><p class="caption" style="margin:15px 3px">Your place is saved in each document.</p></div></main>${nav("groups")}`;
}
function collectionRows() {
  const list = collectionMatches();
  return list.length
    ? docRows(list, true)
    : `<div class="empty">${icon("search")}<h3>No matches</h3><p>Try a title, “quiet”, or a different format.</p></div>`;
}
function collection() {
  return `<div class="heading"><div class="row between"><div><div class="eyebrow">KEPT CLOSE, ON THIS DEVICE</div><h1>Collection</h1></div>${btn("storage", "Storage and Collection settings", "storage")}</div><p class="subtitle">Your documents. Their stories, preserved.</p></div><main class="scroll"><div class="content"><div class="field">${icon("search")}<input id="collection-search" aria-label="Search Collection titles and sample text" placeholder="Search titles and text" value="${escapeHtml(state.query)}"></div><div class="chips">${["All", "PDF", "EPUB", "MD"].map((f) => `<button class="chip ${state.filter === f ? "selected" : ""}" data-action="filter:${f}">${f === "MD" ? "Markdown" : f}</button>`).join("")}</div><div class="section-title"><h2>Latest documents</h2><span id="collection-count" role="status">${collectionCount()}</span></div><div id="collection-results">${collectionRows()}</div><div class="archive-summary"><span>${state.collection ? "Local copies & history enabled" : "New captures are off"}</span><span>Sample library</span></div></div></main>${nav("collection")}`;
}
function history() {
  return `${header("History", `${d().title} · ${d().ext}`, "reader", "more")}<main class="scroll"><div class="content"><div class="card history-intro">${thumb(d())}<div><h3>${d().title}</h3><small>3 saved versions · 12.8 MiB stored</small></div></div><p class="caption" style="margin-bottom:25px">A little history. A way back.</p><div class="timeline"><div class="revision latest"><div class="revision-heading">Today, 09:18 <span class="pill">Latest</span></div><p>Linked original · On this device</p><div class="revision-card"><button data-action="latest">Open current original ${icon("arrow")}</button><p>Current sample document</p></div></div><div class="revision"><div class="revision-heading">18 September, 16:42 <span class="pill gold">${state.kept ? "Kept" : "Saved"}</span></div><p>Saved copy · 1.2 MiB unique blocks</p><div class="revision-card"><button data-action="older:18">Open this version ${icon("arrow")}</button><p>Earlier sample revision</p><div class="revision-actions"><button data-action="keep">${state.kept ? "Unkeep" : "Keep"} version</button><button data-action="export:18">Save a copy</button></div></div></div><div class="revision"><div class="revision-heading">12 September, 10:05</div><p>First saved copy · 0.6 MiB unique blocks</p><div class="revision-card"><button data-action="older:12">Open this version ${icon("arrow")}</button><p>First sample revision</p></div></div></div><div class="info-box">${icon("shield")}Versions share unchanged blocks. Your originals stay in place.</div></div></main>`;
}
function storage() {
  return `${header("Storage", "Collection · Sample accounting", "collection", "storageinfo")}<main class="scroll"><div class="content"><div class="card usage-card"><div class="eyebrow">RETAINED HISTORY</div><div class="usage-number">${state.cleaned ? "286" : "312"} <span>MiB of 1 GiB</span></div><div class="usage-bar"><i></i><i></i><i></i></div><div class="legend"><span><b></b>Document blocks</span><span><b style="background:#9bae91"></b>Index & manifests</span></div><p class="caption" style="margin-top:15px">${state.cleaned ? "28%" : "30%"} of archive limit · 18.4 GiB available on device</p></div><div class="stat"><span>Shared bytes saved<small>Logical versions minus unique retained blocks</small></span><strong>428 MiB</strong></div><div class="stat"><span>Temporary files<small>Active reader, previews and warm cache</small></span><strong>${state.cleaned ? "12" : "48"} MiB</strong></div><div class="stat"><span>Total app-owned data<small>Archive + temporary, excluding application</small></span><strong>${state.cleaned ? "298" : "360"} MiB</strong></div><div class="stat"><span>Protected history<small>Kept versions & sole saved copies</small></span><strong>126 MiB</strong></div><div class="stat"><span>Archive limit</span><button class="text-button" data-action="limit">1 GiB ${icon("chevron")}</button></div><div class="info-box">${icon("shield")}Cleanup respects Keep and the only saved copy of an unavailable original. Originals are never deleted.</div><button class="primary" data-action="cleanup">Review cleanup</button><button class="text-button" style="width:100%;margin-top:8px" data-action="togglecollection">${state.collection ? "Turn off new captures" : "Enable new captures"}</button><p class="caption" style="text-align:center">Illustrative figures, not measurements of your device.</p></div></main>`;
}
